{
 "$schema": "schema-driven/page@v1",
 "kind": "board",
 "head": {
  "badges": [
   "join('', ['第', to_string(this.round), '回'])"
  ],
  "lead": "this.intro"
 },
 "sections": [
  {
   "heading": "現在地",
   "body": [
    {
     "component": "document",
     "value": "{kind:'document', title:'論点の一覧', sections:[{heading:'論点の一覧', blocks:[{type:'table', columns:['論点','状態','いまの答え'], rows: this.topics[*].[join(' ', [id, name]), view('#/$defs/topic/properties/status', status), answer.text]}]}]}"
    },
    {
     "text": "いま見る論点"
    },
    {
     "component": "jump",
     "each": "this.queue",
     "label": "join('　', [topic, why])",
     "to": "topic"
    },
    {
     "text": "この回で変わったところ"
    },
    {
     "component": "jump",
     "each": "this.topics[].changes[]",
     "label": "join('　', [id, why])",
     "to": "id"
    }
   ]
  },
  {
   "heading": "論点",
   "body": [
    {
     "component": "tabs",
     "items": "this.topics",
     "label": "view('#/$defs/topic', @)",
     "id": "id",
     "body": [
      {
       "component": "inline",
       "value": "question"
      },
      {
       "component": "mark",
       "show": "changes[?field=='answer']",
       "each": "changes[?field=='answer']",
       "id": "id",
       "after": "after",
       "before": "before",
       "why": "why"
      },
      {
       "component": "document",
       "value": "{kind:'document', title:'答え', sections:[{heading:'答え', blocks:[!(changes[?field=='answer']) && {type:'paragraph', text: answer.text, strong:`true`}, answer.details && {type:'list', items: answer.details}][?@]}]}"
      },
      {
       "component": "tabs",
       "show": "images",
       "items": "images",
       "label": "view('#/$defs/image', @)",
       "body": [
        {
         "component": "svg",
         "show": "kind=='figure'",
         "value": "svg"
        },
        {
         "component": "embed",
         "show": "kind=='ui'",
         "html": "html",
         "title": "caption"
        },
        {
         "component": "document",
         "show": "kind=='code'",
         "value": "{kind:'document', title:caption, sections:[{heading:caption, blocks:[{type:'code', language: language, text: text}]}]}"
        },
        "caption"
       ]
      },
      {
       "component": "document",
       "show": "grounds || rejected",
       "value": "{kind:'document', title:'裏づけ', sections:[{heading:'裏づけ', blocks:[grounds && {type:'fold', summary:'根拠', blocks:[{type:'table', columns:['結論のどこを支えるか','もとにしたこと','その出どころ'], rows: grounds[*].[supports, basis, join(' ', [tag, source])]}]}, rejected && {type:'fold', summary:'採らなかった案', blocks:[{type:'table', columns:['案','採らなかった理由'], rows: rejected[*].[option, reason]}]}][?@]}]}"
      },
      {
       "component": "choose",
       "show": "status=='open'",
       "name": "join('.', [id, 'verdict'])",
       "options": [
        {
         "value": "approved",
         "label": "承認する"
        },
        {
         "value": "returned",
         "label": "差し戻す"
        },
        {
         "value": "unanswered",
         "label": "まだ答えない"
        }
       ]
      },
      {
       "component": "write",
       "show": "status=='open'",
       "name": "join('.', [id, 'reason'])",
       "label": {
        "text": "差し戻す理由（自由に書く）"
       }
      },
      {
       "component": "write",
       "show": "status=='open'",
       "name": "join('.', [id, 'note'])",
       "label": {
        "text": "書き足し（承認でも差し戻しでも書ける。書かなくても進む）"
       }
      }
     ]
    }
   ]
  },
  {
   "heading": "送る",
   "show": "this.topics[?status=='open']",
   "body": [
    {
     "component": "send",
     "label": {
      "text": "まとめて送る"
     },
     "to": "answers"
    },
    {
     "text": "送ったあと、チャットで一言もらう必要がある。"
    }
   ]
  }
 ]
}
